import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import cp from 'node:child_process';import {chromium} from 'playwright-core';
import Core from '../search_semantic_v3_core_r4.js';import Hybrid from '../search_semantic_hybrid_r6.js';
const PROTOCOL='pls_v16/CALIBRATION_PROTOCOL_V2.json',PROTOCOL_AUTHORITY_COMMIT='5c89b2cb7abac92987f403ec6c6f0e3c443b35eb';
const CONTRACT='pls_v16/BINDING_CONTRACT.json',CONTRACT_SHA='6e8558b4545c1084b3a8342eb2f66611de97dc2e78db46f60919666313164140';
const PACK=process.env.PLS_V16_PACK_DIR||'wip-pls-v16-vector-build',META=process.env.PLS_V16_METADATA||'wip-current-semantic-pack/metadata.jsonl',MASK=process.env.PLS_V16_MASK||'wip-current-semantic-pack/jesus_mask.bits',OUT=process.env.PLS_V16_CAL_OUT||'wip-pls-v16-calibration-v2',PORT=Number(process.env.PLS_V16_CAL_PORT||8769);
const ok=(c,m)=>{if(!c)throw new Error(m);},shaBytes=b=>crypto.createHash('sha256').update(b).digest('hex'),sha=p=>shaBytes(fs.readFileSync(p));
fs.mkdirSync(OUT,{recursive:true});ok(sha(CONTRACT)===CONTRACT_SHA,'BINDING_CONTRACT_SHA');
const frozen=cp.execFileSync('git',['show',PROTOCOL_AUTHORITY_COMMIT+':'+PROTOCOL],{maxBuffer:2*1024*1024}),current=fs.readFileSync(PROTOCOL);ok(Buffer.compare(frozen,current)===0,'V2_PROTOCOL_MUTATED_AFTER_FREEZE');
const protocol=JSON.parse(current),contract=JSON.parse(fs.readFileSync(CONTRACT,'utf8'));ok(protocol.status==='FROZEN_BEFORE_V2_BLIND_OUTCOMES','V2_PROTOCOL_STATUS');ok(protocol.binding_contract_sha256===CONTRACT_SHA&&protocol.pack_id===contract.pack_id,'V2_PROTOCOL_BINDING');
const policy=protocol.frozen_policy;ok(policy&&policy.policy_id==='HYBRID_DENSE_ABSTENTION_V1'&&policy.close_enabled===false&&Number.isFinite(Number(policy.possible_min_dense))&&Number(policy.possible_min_channels)===2,'V2_POLICY');
const metaText=fs.readFileSync(META,'utf8'),passages=metaText.trimEnd().split(/\r?\n/).filter(Boolean).map(JSON.parse);ok(passages.length===contract.chunker.expected_passages,'PASSAGE_COUNT');
const vb=fs.readFileSync(path.join(PACK,'vectors.i8')),nb=fs.readFileSync(path.join(PACK,'inverse_norms.f32le')),jb=fs.readFileSync(MASK);ok(vb.length===passages.length*contract.model.embedding_dim,'VECTOR_BYTES');ok(nb.length===passages.length*4,'NORM_BYTES');
const vectors=new Int8Array(vb.buffer,vb.byteOffset,vb.byteLength),norms=new Float32Array(nb.buffer.slice(nb.byteOffset,nb.byteOffset+nb.byteLength)),jesusBits=new Uint8Array(jb.buffer,jb.byteOffset,jb.byteLength);
const index=Core.createIndex({passages,dim:contract.model.embedding_dim,vectors,inverseNorms:norms,jesusBits}),bm25=Hybrid.buildBm25(passages,jesusBits);
const root='/tmp/ldc-pls-v16-calibration-v2',modelDir=path.join(root,'model'),onnxDir=path.join(modelDir,'onnx'),runtimeDir=path.join(root,'runtime');fs.rmSync(root,{recursive:true,force:true});fs.mkdirSync(onnxDir,{recursive:true});fs.mkdirSync(runtimeDir,{recursive:true});
for(const f of contract.model.tokenizer_and_config_files)fs.copyFileSync(f.path,path.join(modelDir,path.basename(f.path)));for(const f of contract.runtime.files)fs.copyFileSync(f.path,path.join(runtimeDir,path.basename(f.path)));
const joined=Buffer.concat(contract.model.delivery.parts.map(x=>fs.readFileSync(x.path)));ok(joined.length===contract.model.delivery.original_model_bytes,'MODEL_BYTES');ok(shaBytes(joined)===contract.model.model_sha256,'MODEL_HASH');fs.writeFileSync(path.join(onnxDir,'model_int8.onnx'),joined);fs.copyFileSync('.github/wip-semantic-v16-query-embed.html',path.join(root,'query.html'));
const server=cp.spawn('python3',['-m','http.server',String(PORT),'--bind','127.0.0.1'],{cwd:root,stdio:['ignore','ignore','inherit']});let browser=null;
function targetRank(rows,target){const i=(rows||[]).findIndex(x=>String(x.entry_id)===String(target));return i<0?null:i+1;}
async function evaluateQuery(page,id,text,target=null){
 const raw=await page.evaluate(async q=>await window.embedQuery(q),text),raw2=await page.evaluate(async q=>await window.embedQuery(q),text);ok(raw.length===raw2.length&&raw.every((v,i)=>Object.is(Number(v),Number(raw2[i]))),'QUERY_SINGLETON_NONDETERMINISTIC '+id);
 const vec=Float32Array.from(raw),opt={sourceMode:'enriched',volMin:0,volMax:0,dateIso:null,year:0,stableRef:null,jesus:false};
 const dense=index.denseSearch(vec,{...opt,candidatePool:160,maxResults:160,collapseThreshold:.5}),sparse=Hybrid.bm25Search(bm25,text,{...opt,maxCandidates:160}),fused=Hybrid.fuse(dense.dense_candidates,sparse.results,{maxResults:20}),features=Hybrid.features(fused),decision=Hybrid.classify(fused,policy);
 return {id,text_sha256:shaBytes(Buffer.from(text,'utf8')),query_singleton_deterministic:true,target_entry_id:target,target_rank:target?targetRank(fused,target):null,top_entry_id:fused[0]?.entry_id||null,top20:fused.map(x=>x.entry_id),features,decision,dense_candidates:dense.dense_candidates.length,bm25_candidates:sparse.results.length};
}
try{
 await new Promise(r=>setTimeout(r,900));const exe=process.env.CHROME_PATH||'/usr/bin/google-chrome';ok(fs.existsSync(exe),'CHROME_NOT_FOUND');browser=await chromium.launch({headless:true,executablePath:exe,args:['--no-sandbox']});const page=await browser.newPage();page.setDefaultTimeout(180000);await page.goto('http://127.0.0.1:'+PORT+'/query.html',{waitUntil:'load'});await page.waitForFunction(()=>document.querySelector('#status')?.textContent==='module-ready');await page.evaluate(()=>window.initModel());await page.waitForFunction(()=>document.querySelector('#status')?.textContent==='ready');
 const positives=[];for(const q of protocol.positives)positives.push(await evaluateQuery(page,q.id,q.text,q.target_entry_id));
 const dev=[];for(const q of protocol.development_negatives)dev.push(await evaluateQuery(page,q.id,q.text));
 const positiveGate=positives.every(x=>x.target_rank!=null&&x.target_rank<=10&&x.features.channels>=Number(policy.possible_min_channels)&&x.decision.state==='possible');
 const devGate=dev.every(x=>x.decision.state==='abstain');
 const hold=[];if(positiveGate&&devGate){for(const q of protocol.blind_holdout_negatives)hold.push(await evaluateQuery(page,q.id,q.text));}
 const holdGate=positiveGate&&devGate&&hold.length===protocol.blind_holdout_negatives.length&&hold.every(x=>x.decision.state==='abstain');
 const probes=[];for(const q of protocol.revealed_truth_neutral_probes||[])probes.push(await evaluateQuery(page,q.id,q.text));
 const neutralClassifier=Hybrid.classify([{rrf60_score:.03,dense_score:Number(policy.possible_min_dense)+.001,source_ranks:{dense_96_72:1,bm25_96_72:1}}],policy);
 const truthNeutralGate=neutralClassifier.state==='possible'&&neutralClassifier.label==='Quelques pistes possibles'&&policy.close_enabled===false;
 const qualified=positiveGate&&devGate&&holdGate&&truthNeutralGate;
 const report={schema:'ldc-pls-v16-calibration-evidence-v2',status:qualified?'PASS_QUALIFIABLE':'FAIL_ENGINEERING_ONLY',protocol_authority_commit:PROTOCOL_AUTHORITY_COMMIT,protocol_sha256:sha(PROTOCOL),predecessor_v1_status:'FAIL_ENGINEERING_ONLY',binding_contract_sha256:CONTRACT_SHA,pack_id:contract.pack_id,pack_assets:{metadata_sha256:sha(META),vectors_sha256:sha(path.join(PACK,'vectors.i8')),inverse_norms_sha256:sha(path.join(PACK,'inverse_norms.f32le')),jesus_mask_sha256:sha(MASK)},retrieval:{dense_candidate_depth:160,bm25_candidate_depth:160,rrf_k:60,output_depth:20},selection:{policy,policy_changed_after_v1_blind_failure:false},gates:{owner_real_query_gate:positiveGate?'PASS':'FAIL',hard_negative_gate:devGate?'PASS':'FAIL',blind_unrelated_query_gate:holdGate?'PASS':'FAIL',truth_neutrality_gate:truthNeutralGate?'PASS':'FAIL'},positives,development_negatives:dev,blind_holdout_negatives:hold,revealed_truth_neutral_probes:probes,close_label_authorized:false,entailment_claim:false,doctrinal_truth_validation_claim:false,posthoc_v2_rule_changes:0,production_claim:false,deployment_authorized:false};
 fs.writeFileSync(path.join(OUT,'calibration_evidence_v2.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({status:report.status,policy,gates:report.gates,positive_ranks:positives.map(x=>x.target_rank),blind:hold.map(x=>({id:x.id,state:x.decision.state,score:x.features.top_dense_score,channels:x.features.channels}))},null,2));if(!qualified)process.exitCode=4;
}finally{if(browser)await browser.close().catch(()=>{});server.kill('SIGTERM');}
